/**
 * One-time script — populates ingredients, warnings, paoMonths on every perfume product
 * and uploads SDS PDFs to Supabase Storage, then sets sdsUrl on diffuser products.
 *
 * Run: npx ts-node -P tsconfig.json prisma/update-compliance.ts
 */

import { PrismaClient } from '@prisma/client';
import { createClient } from '@supabase/supabase-js';
import * as fs from 'fs';
import * as path from 'path';
import * as dotenv from 'dotenv';

dotenv.config({ path: path.join(__dirname, '../.env') });

const prisma = new PrismaClient();
const supabase = createClient(
  process.env.SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!,
);

const DOCS_DIR = path.join(__dirname, '../../../docs');
const SDS_BUCKET = 'product-images';

// ─── INCI/warnings/PAO data keyed by base_code (= primary variant SKU) ──────

interface ComplianceEntry {
  inci: string;
  warnings: string;
  paoMonths: number;
}

