async function main() {
  let complianceUpdated = 0;
  let complianceSkipped = 0;

  console.log('Updating compliance data (ingredients, warnings, PAO)...');

  for (const [baseCode, data] of Object.entries(COMPLIANCE)) {
    // Find product whose primary variant SKU = base_code
    const product = await prisma.product.findFirst({
      where: { variants: { some: { sku: baseCode } } },
      select: { id: true, name: true },
    });

    if (!product) {
      console.warn(`  SKIP: no product found for code ${baseCode}`);
      complianceSkipped++;
      continue;
    }

    await prisma.product.update({
      where: { id: product.id },
      data: {
        ingredients: data.inci,
        warnings: data.warnings,
        paoMonths: data.paoMonths,
      },
    });

    complianceUpdated++;
    console.log(`  ✓ ${baseCode} → ${product.name}`);
  }

  console.log(`\nCompliance: ${complianceUpdated} updated, ${complianceSkipped} skipped\n`);

  // ── Upload SDS PDFs and set sdsUrl on diffuser products ──────────────────

  console.log('Uploading SDS PDFs to Supabase...');
  let sdsUpdated = 0;

  for (const [baseCode, filename] of Object.entries(SDS_FILES)) {
    const filePath = path.join(DOCS_DIR, filename);

    if (!fs.existsSync(filePath)) {
      console.warn(`  SKIP: SDS file not found at ${filePath}`);
      continue;
    }

    const product = await prisma.product.findFirst({
      where: { variants: { some: { sku: baseCode } } },
      select: { id: true, name: true },
    });

    if (!product) {
      console.warn(`  SKIP: no product found for diffuser code ${baseCode}`);
      continue;
    }

    const buffer = fs.readFileSync(filePath);
    const storagePath = `sds/${filename}`;

    const { error } = await supabase.storage
      .from(SDS_BUCKET)
      .upload(storagePath, buffer, { contentType: 'application/pdf', upsert: true });

    if (error) {
      console.error(`  ERROR uploading SDS for ${baseCode}:`, error.message);
      continue;
    }

    const { data: urlData } = supabase.storage
      .from(SDS_BUCKET)
      .getPublicUrl(storagePath);

    await prisma.product.update({
      where: { id: product.id },
      data: { sdsUrl: urlData.publicUrl },
    });

    sdsUpdated++;
    console.log(`  ✓ ${baseCode} (${product.name}) → ${urlData.publicUrl}`);
  }

  console.log(`\nSDS: ${sdsUpdated} uploaded and linked\n`);
  console.log('Done!');
}

main()
  .catch((err) => { console.error(err); process.exit(1); })
  .finally(() => prisma.$disconnect());
